const cases = [
  { scenario_id: 'SCN001', member_id: 'M1001', member_inquiry: "My MRI claim was denied because insurance says there was no authorization, but my doctor's office says it was approved.", service_code: 'MRI-SIM-001', service_date: '2026-05-14' },
  { scenario_id: 'SCN002', member_id: 'M1002', member_inquiry: "My MRI claim was denied because authorization wasn't found.", service_code: 'MRI-SIM-001', service_date: '2026-06-10' },
  { scenario_id: 'SCN003', member_id: 'M1003', member_inquiry: 'My doctor\'s office says my insurance is inactive, but I enrolled months ago.', service_code: 'MRI-SIM-001', service_date: '' },
  { scenario_id: 'SCN004', member_id: 'M1004', member_inquiry: "My claim was denied, but the authorization system isn't responding.", service_code: 'MRI-SIM-001', service_date: '2026-07-18' }
];
return cases.map(testCase => ({ json: testCase }));

const expected = {
  SCN001: { root_cause: 'AUTHORIZATION_CLAIM_LOCATION_MISMATCH', action: 'CLAIM_RECONSIDERATION' },
  SCN002: { root_cause: 'PRIOR_AUTHORIZATION_MISSING', action: 'PROVIDER_INITIATE_AUTHORIZATION' },
  SCN003: { root_cause: 'ELIGIBILITY_ENROLLMENT_MISMATCH', action: 'ELIGIBILITY_RECORD_REVIEW' },
  SCN004: { root_cause: 'AUTHORIZATION_CLAIM_LINK_FAILURE', action: 'CLAIM_RECONSIDERATION' }
};
return $input.all().map(item => {
  const state = item.json;
  const exp = expected[state.scenario_id];
  const failures = [];
  if (!exp) failures.push('Unknown scenario returned');
  if (exp && state.root_cause !== exp.root_cause) failures.push('Root cause mismatch');
  if (exp && state.recommended_action !== exp.action) failures.push('Recommended action mismatch');
  const called = Array.isArray(state.agents_called) ? state.agents_called : [];
  if (state.scenario_id === 'SCN001') {
    if (!called.includes('PROVIDER')) failures.push('Provider was not called');
    if (state.member_transfer_required !== false) failures.push('Member transfer should be false');
  }
  if (state.scenario_id === 'SCN002') {
    if (called.includes('PROVIDER')) failures.push('Provider should not be called');
    if (state.member_transfer_required !== false) failures.push('Member transfer should be false');
  }
  if (state.scenario_id === 'SCN003') {
    for (const unnecessary of ['CLAIMS', 'AUTHORIZATION', 'AUTHORIZATION_ALTERNATE', 'PROVIDER']) {
      if (called.includes(unnecessary)) failures.push(unnecessary + ' should not be called');
    }
  }
  if (state.scenario_id === 'SCN004') {
    if (!Array.isArray(state.tool_errors) || state.tool_errors.filter(error => error.tool === 'AUTHORIZATION').length < 2) failures.push('Expected at least two authorization errors');
    if (Number(state.authorization_attempt_count) < 2) failures.push('Expected at least two authorization attempts');
    if (state.authorization_alternate_used !== true) failures.push('Alternate authorization lookup was not used');
    if (state.authorization?.status !== 'SUCCESS') failures.push('Authorization did not eventually succeed');
  }
  const result = { scenario_id: state.scenario_id || 'UNKNOWN', passed: failures.length === 0, failures, actual: { workflow_status: state.workflow_status, root_cause: state.root_cause, recommended_action: state.recommended_action, member_transfer_required: state.member_transfer_required, agents_called: called, tool_error_count: Array.isArray(state.tool_errors) ? state.tool_errors.length : 0, authorization_attempt_count: state.authorization_attempt_count, authorization_alternate_used: state.authorization_alternate_used, authorization_status: state.authorization?.status ?? null } };
  if (state.debug_trace_enabled === true) {
    const trace = Array.isArray(state.debug_trace) ? state.debug_trace : [];
    result.debug_trace = trace;
    result.first_error_event = trace.find(entry => entry && (entry.status === 'ERROR' || entry.status === 'FAILURE')) || null;
  }
  return { json: result };
});

const results = $input.all().map(item => item.json);
const passed = results.filter(result => result.passed).length;
return [{ json: { suite: 'OneCall AI Agentic Scenarios', status: passed === results.length ? 'PASS' : 'FAIL', total: results.length, passed, failed: results.length - passed, results } }];
